function DraftEditor({draft,job,application,busy,onSave,onReady,onApply}:{draft:Draft;job:Job;application?:ApplicationRequest;busy:boolean;onApply:()=>Promise<void>;onSave:(text:string)=>Promise<Packet|null>;onReady:()=>Promise<Packet|null>}){
 const [text,setText]=useState(draft.text),[confirmed,setConfirmed]=useState(false);const dirty=text!==draft.text;
 return <article id={`application-materials-${draft.id}`} className="panel draft-card"><div className="draft-heading"><div><span className="eyebrow">{application?'APPLY REQUEST':'APPLICATION MATERIALS'}</span><h2>{job.title}</h2><p>{job.company} · Version {draft.version}</p></div><span className="badge">{application?(application.status==='applied'?'APPLIED':application.status==='queued'?'QUEUED':application.status==='processing'?'APPLYING':application.status==='uncertain'?'CHECK OUTCOME':'NEEDS ACTION'):'NOT REQUESTED'}</span></div>{application&&<div className="application-status" role="status"><strong>{application.status==='applied'?'Employer confirmed application':application.status==='queued'?'Waiting for browser runner':application.status==='processing'?'Agent working on employer website':application.status==='uncertain'?'Submission outcome needs checking':'Application not submitted'}</strong><p>{application.status==='applied'?'The employer confirmation and receipt were recorded.':application.status==='processing'?'The browser runner is working through the employer form. Submission is not confirmed yet.':application.status==='queued'?'Keep your connected browser runner open. The request is queued with its chosen CV.':application.status==='uncertain'?'Check the employer before trying again; the outcome is unknown.':application.reason==='candidate_review_required'?'Review the chosen CV and update this older request before using these materials.':application.reason==='materials_changed'?'Your materials changed. Review the latest CV and draft before taking the next step.':'Connect the CV application agent in Settings and queue this request from Applications, or open the employer application page yourself.'}</p><small>Requested {date(application.at)}</small></div>}<label htmlFor={`draft-${draft.id}`}>Application text</label><textarea id={`draft-${draft.id}`} className="draft-input" value={text} maxLength={20000} onChange={e=>{setText(e.target.value);setConfirmed(false);}}/><div className="draft-meta"><span>{text.trim()?text.trim().split(/\s+/).length:0} words</span><span>{dirty?'Unsaved edits':`Saved ${date(draft.updatedAt)}`}</span></div><label className="check-label"><input type="checkbox" checked={confirmed} disabled={dirty||draft.status==='ready'} onChange={e=>setConfirmed(e.target.checked)}/><span>I reviewed this exact saved text and my chosen CV.</span></label><div className="form-foot"><span className="subtle">{dirty?'Save your edits before reviewing.':application?.status==='applied'?'Employer confirmation recorded.':draft.status==='ready'?'Materials reviewed. Check the application status above.':'Review your saved materials before using them.'}</span><div className="row-actions"><Button className="quiet" disabled={busy||!dirty||text.trim().length<20} onClick={()=>void onSave(text)}>Save edits</Button><Button disabled={busy||dirty||!confirmed||draft.status==='ready'} onClick={()=>void onReady()}><Check size={16}/>Mark reviewed</Button>{!application&&<Button disabled={busy||dirty} onClick={()=>void onApply()}>Apply<ArrowRight size={16}/></Button>}</div></div>{job.url&&<a className="source-link button quiet" href={job.applyUrl||job.url} target="_blank" rel="noopener noreferrer">Open application page<ExternalLink size={14}/></a>}<p className="subtle">Opening the page does not confirm submission. A request becomes Applied only after the employer confirmation is recorded.</p></article>;
}
